    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target) public payable {
        require(_target != address(c), "target must not be c");
        uint cBefore = address(c).balance;
        bool reverted;
        c.sendMoney(_target, 0, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(address(c).balance == cBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

